import xml.etree.ElementTree as ET

path='/Users/wangyifan/Projects/auto_adapter2.0/AA1/assets/mjcf/capabilities/piper/piper_fixed.xml'
tree=ET.parse(path); root=tree.getroot()
wb=root.find('worldbody')

# body tree
def walk(b, depth=0, parent=None):
    name=b.get('name')
    print('  '*depth+ (name or '?'))
    for child in b.findall('body'):
        walk(child, depth+1, name)
for b in wb.findall('body'):
    walk(b)

# collect joints in document order
joints=[]
def collect(b):
    for j in b.findall('joint'):
        joints.append(j)
    for c in b.findall('body'):
        collect(c)
for b in wb.findall('body'):
    collect(b)
print('\nJOINTS:')
for j in joints:
    print(j.get('name'), j.get('type'), j.get('axis'), j.get('range'), 'class=',j.get('class'))
